//! Round trip and typed reading of a realistic `sakura.ini`.
//!
//! `data/sakura_sample.ini` is made to look like a file written by Sakura (`CShareData_IO.cpp`): the header
//! comment of `ShareData_IO_2`, UTF-8 with a BOM, CRLF (UME Editor writes the line ends of the OS in new files), sections in the order `CProfile` writes them with keys
//! sorted by UTF-16 code unit and a blank line after each section, values with Japanese text, `=` and
//! backslashes in values, and the entry forms of `Types(N)`, `Font` and `MRU`. It was generated by a script
//! (not by Sakura itself), from the key names in `CShareData_IO.cpp` and the defaults in `CType.cpp`.

use ume_config::settings::color::names;
use ume_config::settings::types::{code_type, eol_type, wrap_method};
use ume_config::settings::{TypeSettings, ViewFont, types_count};
use ume_config::{FileEncoding, Profile};

const SAMPLE: &[u8] = include_bytes!("data/sakura_sample.ini");
const HEADER: &str = " sakura.ini テキストエディタ設定ファイル";

#[test]
fn reading_and_writing_back_gives_the_same_bytes() {
    let p = Profile::from_bytes(SAMPLE);
    assert_eq!(p.encoding(), FileEncoding::Utf8);
    assert!(p.has_bom());
    assert_eq!(p.to_bytes(), SAMPLE);
}

#[test]
fn sakura_style_output_of_a_sakura_file_is_the_same_file() {
    // Sakura writes this file the same way: sorted keys, blank line after sections, header comment.
    // The line ends are the ones of the OS (the sample has CRLF, Sakura's).
    let p = Profile::from_bytes(SAMPLE);
    let mut want = SAMPLE.to_vec();
    if !cfg!(windows) {
        want = String::from_utf8(want)
            .unwrap()
            .replace("\r\n", "\n")
            .into_bytes();
    }
    assert_eq!(p.to_sakura_bytes(Some(HEADER)), want);
}

#[test]
fn values_with_japanese_text_and_equals_signs() {
    let p = Profile::from_bytes(SAMPLE);
    assert_eq!(
        p.get("MRU", "MRU[00].szPath"),
        Some("C:\\Users\\山田 太郎\\Documents\\メモ.txt")
    );
    // Only the first `=` splits the line.
    assert_eq!(
        p.get("MRU", "MRU[01].szPath"),
        Some("D:\\work\\日報=2026.log")
    );
    assert_eq!(p.get("Types(1)", "szTypeName"), Some("テキスト"));
    assert_eq!(p.get_i32("MRU", "MRU[01].nType"), Some(-1));
    assert_eq!(
        p.section_names().collect::<Vec<_>>(),
        [
            "Common", "Font", "MRU", "Other", "Types(0)", "Types(1)", "Types(2)", "KeyBind"
        ]
    );
}

/// The same file as the user would have it after years of editing by hand and by other tools: LF line ends,
/// no BOM (read as Shift_JIS), comments, blank lines in odd places, keys out of order, an entry before the
/// first section, a repeated section and a repeated key.
fn user_edited_shift_jis() -> Vec<u8> {
    let text = "junk before the first section\n\
        ; my notes: 日本語のコメント\n\
        [Types(0)]\n\
        szTypeName=基本\n\
        nInts=0,100,0,8,-1,-1,0,1,1,0,0,0\n\
        // another comment style\n\
        bAutoIndent=0\n\
        szTypeName=ignored second value\n\
        \n\
        \n\
        [Font]\n\
        lfFaceName=ＭＳ ゴシック\n\
        lf=-13,0,0,0,400,0,0,0,128,3,2,1,49\n\
        nPointSize=100\n\
        [Types(0)]\n\
        nLineSpace=7\n\
        [Other]\n\
        nTypesCount=1\n\
        untouched=日本語";
    let (bytes, _, had_errors) = encoding_rs::SHIFT_JIS.encode(text);
    assert!(!had_errors);
    bytes.into_owned()
}

#[test]
fn a_user_edited_file_comes_back_byte_for_byte() {
    let bytes = user_edited_shift_jis();
    let p = Profile::from_bytes(&bytes);
    assert_eq!(p.encoding(), FileEncoding::ShiftJis);
    assert!(!p.has_bom());
    assert_eq!(p.to_bytes(), bytes);
}

#[test]
fn typed_settings_of_a_user_edited_file() {
    let p = Profile::from_bytes(&user_edited_shift_jis());
    // The first section with a name and the first of a repeated key are used (CProfile::GetProfileData).
    let t = TypeSettings::read(&p, 0);
    assert_eq!(t.type_name, "基本");
    assert_eq!(t.max_line_ketas, 100);
    assert_eq!(t.tab_space, 8);
    assert!(!t.auto_indent);
    // `nLineSpace` is in the second `[Types(0)]`, which Sakura never looks at.
    assert_eq!(t.line_space, TypeSettings::basic().line_space);
    assert_eq!(types_count(&p), 1);
    let f = ViewFont::read(&p);
    assert_eq!(f.font.log_font.face_name, "ＭＳ ゴシック");
}

#[test]
fn changing_one_setting_changes_only_that_line() {
    let bytes = user_edited_shift_jis();
    let mut p = Profile::from_bytes(&bytes);
    p.set_i32("Types(0)", "bAutoIndent", 1).unwrap();
    let out = p.to_bytes();
    let at = bytes
        .windows(13)
        .position(|w| w == b"bAutoIndent=0")
        .unwrap();
    let mut want = bytes.clone();
    want[at + 12] = b'1';
    assert_eq!(out, want);
    assert_eq!(
        Profile::from_bytes(&out).get_i32("Types(0)", "bAutoIndent"),
        Some(1)
    );
}

#[test]
fn reads_the_phase_1_settings_of_the_sample() {
    let p = Profile::from_bytes(SAMPLE);
    assert_eq!(types_count(&p), 3);

    let font = ViewFont::read(&p);
    assert_eq!(font.font.log_font.face_name, "ＭＳ ゴシック");
    assert_eq!(font.font.point_size, 100);
    assert_eq!(font.font.log_font.height, -13);
    assert_eq!(font.font.log_font.char_set, 0x80);
    assert!(font.fixed_pitch);

    let basic = TypeSettings::read(&p, 0);
    assert_eq!(basic.type_name, "基本");
    assert_eq!(basic.max_line_ketas, 10240);
    assert_eq!(basic.tab_space, 4);
    assert_eq!(basic.text_wrap_method, wrap_method::NONE);
    assert_eq!(basic.default_codetype, code_type::UTF8);
    assert_eq!(basic.default_eoltype, eol_type::CRLF);
    assert!(!basic.default_bom);
    assert!(!basic.kinsoku_head_enabled);
    let c = &basic.colors;
    assert!(c.get(names::LINE_NUMBER).unwrap().disp);
    assert!(c.get(names::TAB).unwrap().disp);
    assert!(c.get(names::EOL).unwrap().disp);
    assert!(c.get(names::EOF).unwrap().disp);
    assert!(!c.get(names::HALF_SPACE).unwrap().disp);
    assert!(!c.get(names::SINGLE_QUOTE).unwrap().disp);

    let text = TypeSettings::read(&p, 1);
    assert_eq!(text.type_name, "テキスト");
    assert_eq!(text.type_exts, "txt,log,1st,err,ps");
    assert_eq!(text.max_line_ketas, 120);
    assert!(text.kinsoku_head_enabled && text.kinsoku_tail_enabled && text.kinsoku_kuto_enabled);
    assert!(text.kinsoku_head.starts_with("!%),.:;?]}"));
    assert!(text.kinsoku_tail.starts_with("$([\\{"));
    assert_eq!(text.kinsoku_kuto, "、。，．､｡,.");
    assert!(text.use_type_font);
    assert_eq!(text.font.log_font.face_name, "BIZ UDゴシック");
    assert_eq!(text.font.point_size, 120);
}

#[test]
fn saving_the_settings_read_from_a_file_keeps_every_line_of_it() {
    // Like Sakura, saving writes every key it knows. A key the file lacks (here: the search colour, which is
    // left out of the sample) is added; the lines that were in the file are untouched and keep their order.
    let mut p = Profile::from_bytes(SAMPLE);
    for i in 0..types_count(&p) {
        TypeSettings::read(&p, i).write(&mut p, i).unwrap();
    }
    ViewFont::read(&p).write(&mut p).unwrap();
    let out = String::from_utf8(p.to_bytes()).unwrap();
    let original = String::from_utf8(SAMPLE.to_vec()).unwrap();
    let mut rest = out.split("\r\n");
    for line in original.split("\r\n") {
        assert!(rest.any(|l| l == line), "lost or moved: {line:?}");
    }
    // A second save changes nothing.
    let mut again = Profile::from_bytes(&p.to_bytes());
    for i in 0..types_count(&again) {
        TypeSettings::read(&again, i).write(&mut again, i).unwrap();
    }
    ViewFont::read(&again).write(&mut again).unwrap();
    assert_eq!(again.to_bytes(), p.to_bytes());
}

#[test]
fn unknown_entries_and_sections_survive_a_settings_change() {
    let mut p = Profile::from_bytes(SAMPLE);
    let mut t = TypeSettings::read(&p, 0);
    t.tab_space = 2;
    t.text_wrap_method = wrap_method::WINDOW_WIDTH;
    t.default_codetype = code_type::SJIS;
    t.write(&mut p, 0).unwrap();
    let out = Profile::from_bytes(&p.to_bytes());
    let back = TypeSettings::read(&out, 0);
    assert_eq!(back.tab_space, 2);
    assert_eq!(back.text_wrap_method, wrap_method::WINDOW_WIDTH);
    assert_eq!(back.default_codetype, code_type::SJIS);
    // Entries the typed structs do not know are still there, with their values.
    let before = Profile::from_bytes(SAMPLE);
    for section in before.section_names() {
        for (k, v) in before.entries(section) {
            let now = out.get(section, k);
            if section == "Types(0)"
                && matches!(k, "nInts" | "nTextWrapMethod" | "eDefaultCodetype")
            {
                continue;
            }
            assert_eq!(now, Some(v), "[{section}] {k}");
        }
    }
    assert_eq!(
        out.section_names().collect::<Vec<_>>(),
        before.section_names().collect::<Vec<_>>()
    );
}

#[test]
fn a_new_settings_file_is_written_like_sakura() {
    let mut p = Profile::new();
    TypeSettings::basic().write(&mut p, 0).unwrap();
    let bytes = p.to_bytes();
    let eol = if cfg!(windows) { "\r\n" } else { "\n" };
    assert!(bytes.starts_with(format!("\u{feff}[Types(0)]{eol}").as_bytes()));
    let back = Profile::from_bytes(&bytes);
    assert_eq!(TypeSettings::read(&back, 0), TypeSettings::basic());
}
